+				model: port,
+				tools: [],
+				cwd: root,
+				sessionsRoot: join(root, "sessions"),
+				permissionMode: "auto",
+				rows: 8,
+				cols: 80,
+				hooks: sink.hooks,
+				slashCommand: customSlashHandler([demoCommand()]),
+			});
